import bruzem

def _extract(value):
    """Extract the numeric part from the value returned by bruzem.find."""
    # If it's a tuple/list with at least two elements, assume the second is the stored value
    if isinstance(value, (list, tuple)) and len(value) >= 2:
        return value[1]
    # If it has a .value attribute, use it
    if hasattr(value, "value"):
        return value.value
    # Otherwise return the value as‑is
    return value

# Build the required mapping
result = {
    "sigma": _extract(bruzem.find("sigma")),
    "kappa": _extract(bruzem.find("kappa")),
}
